head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > displayDayType]<br/>Calendar 컴포넌트의 요일 영역이 렌더링 되는 방법을 설정합니다.",
    "validation" : [
        "미설정 시 기본값 'image' 로 동작하여 요일 영역을 배경 이미지로 렌더링 합니다.",
        "image 설정 시 빈 'div' 요소가 생성되며 CSS 클래스 'w2calendar_day{인덱스}' 에 정의된 배경 이미지로 요일이 시각적으로 표현됩니다.",
        "image 설정 시 텍스트 기반이 아니므로 스크린리더가 요일 정보를 읽을 수 없으며 title 속성에만 요일명이 설정됩니다.",
        "image 설정 시 renderType=component 이면 'td' > 'div' 구조로 렌더링됩니다.",
        "text 설정 시 요일 영역을 축약형 텍스트로 렌더링하며 CSS 클래스 'w2calendar_col_day_text', 'w2calendar_day_text_{인덱스}' 가 적용됩니다.",
        "text 설정 + renderType=component 이면 'td' > 'div' 구조로 렌더링됩니다.",
        "text 설정 + renderType=native 이면 'th' 구조로 렌더링됩니다.",
        "textNative 설정 시 'th' 태그의 축약형 텍스트로 표현되며 scope='col' 속성이 부여됩니다.",
        "textNative 설정 시 renderType 값에 관계없이 항상 'th' 태그로 렌더링됩니다.",
        "textNative 설정 + accessibility=true 이면 'th' 태그에 role='columnheader' 가 추가됩니다.",
        "accessibility=true 이면 displayDayType 속성이 'textNative' 로 강제 설정됩니다.",
        "displayDayType 속성값에 관계없이 토요일은 파란색, 일요일은 빨간색으로 표시됩니다.",
        "renderType=native + displayDayType=image 이면 요일 영역이 'th' 태그에 전체 요일명 텍스트로 표시되며 이미지 모드가 아닌 텍스트 모드로 동작합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        displayDayType : con_displayDayType.getText(),
        renderType : con_renderType.getText(),
        accessibility : con_accessibility.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// [공통] 적용된 displayDayType + accessibility 강제 설정 여부
scwin.getAppliedType = function () {
    let dispType = target1.options.displayDayType;
    let acc = target1.options.accessibility;
    // validation: accessibility=true 이면 displayDayType 이 'textNative' 로 강제 설정됨
    let forced = (acc === true && dispType === 'textNative') ? ' (accessibility=true → textNative 강제 적용)' : '';
    wf_body_bottom.getObj("scwin").setReturnValue("[적용된 displayDayType] '" + dispType + "'" + forced);
}



// [image 모드 전용] 빈 div 요소 + w2calendar_day{인덱스} CSS / textContent 비어있고 title 에 요일명 / native+image 시 텍스트 모드로 동작
scwin.getImageModeInfo = function () {
    let firstCell = target1.render.querySelector("thead tr > *");
    if (!firstCell) return;
    let cellTag = firstCell.tagName.toLowerCase();
    let innerDiv = firstCell.querySelector("div");
    let renderType = target1.options.renderType;

    if (renderType === 'native') {
        // validation: renderType=native + displayDayType=image → th 태그 + 전체 요일명 텍스트 (텍스트 모드 강제)
        wf_body_bottom.getObj("scwin").setReturnValue("[image+native: th 전체 요일명 텍스트 모드] tag='" + cellTag + "', textContent='" + firstCell.textContent + "'");
    } else {
        // validation: image + renderType=component → td > div 구조 / 빈 div 요소 + w2calendar_day{인덱스} CSS 클래스 적용
        // validation: 텍스트 기반 아님 → textContent 비어있고 title 에 요일명 설정됨
        let divClass = innerDiv ? innerDiv.className : '없음';
        let divTitle = innerDiv ? innerDiv.getAttribute('title') : '없음';
        wf_body_bottom.getObj("scwin").setReturnValue("[image+component: td>div 구조] cellTag='" + cellTag + "', innerDiv.className='" + divClass + "'");
        wf_body_bottom.getObj("scwin").setReturnValue("[image: textContent 비어있고 title 에 요일명] textContent='" + firstCell.textContent + "', innerDiv.title='" + divTitle + "'");
    }
}



// [text 모드 전용] 축약형 텍스트 + w2calendar_col_day_text / w2calendar_day_text_{인덱스} CSS 클래스
scwin.getTextModeInfo = function () {
    let firstCell = target1.render.querySelector("thead tr > *");
    if (!firstCell) return;
    let cellTag = firstCell.tagName.toLowerCase();
    let innerDiv = firstCell.querySelector("div");
    let renderType = target1.options.renderType;

    if (renderType === 'native') {
        // validation: text + renderType=native → th 구조
        wf_body_bottom.getObj("scwin").setReturnValue("[text+native: th 구조 + 축약형 텍스트] tag='" + cellTag + "', className='" + firstCell.className + "', textContent='" + firstCell.textContent + "'");
    } else {
        // validation: text + renderType=component → td > div 구조
        let divClass = innerDiv ? innerDiv.className : '없음';
        let divText = innerDiv ? innerDiv.textContent : firstCell.textContent;
        wf_body_bottom.getObj("scwin").setReturnValue("[text+component: td>div 구조 + 축약형 텍스트] cellTag='" + cellTag + "', cellClassName='" + firstCell.className + "', innerDiv.className='" + divClass + "', innerDiv.textContent='" + divText + "'");
    }
}



// [textNative 모드 전용] renderType 무관 th 태그 + 축약형 텍스트 + scope='col' / accessibility=true 시 role='columnheader' 추가
scwin.getTextNativeModeInfo = function () {
    let firstCell = target1.render.querySelector("thead tr > *");
    if (!firstCell) return;
    let acc = target1.options.accessibility;

    // validation: textNative → renderType 무관 항상 th / scope='col' / accessibility=true 시 role='columnheader'
    wf_body_bottom.getObj("scwin").setReturnValue("[textNative: th 태그 + 축약형 + scope='col']"
        + " tag='" + firstCell.tagName.toLowerCase() + "'"
        + ", scope='" + firstCell.getAttribute('scope') + "'"
        + ", textContent='" + firstCell.textContent + "'");
    if (acc === true) {
        wf_body_bottom.getObj("scwin").setReturnValue("[textNative+accessibility=true: role='columnheader'] role='" + firstCell.getAttribute('role') + "'");
    }
}



// [공통] 토요일(파란색)/일요일(빨간색) 색상 (displayDayType 무관)
scwin.getWeekendColor = function () {
    let r = target1.render;
    let sunCell = r.querySelector('thead [class*="w2calendar_day0"], thead [class*="w2calendar_day_text_0"]');
    let satCell = r.querySelector('thead [class*="w2calendar_day6"], thead [class*="w2calendar_day_text_6"]');

    // validation: displayDayType 속성값에 관계없이 토요일 파란색, 일요일 빨간색
    let sunColor = sunCell ? getComputedStyle(sunCell).color : '셀 없음';
    let satColor = satCell ? getComputedStyle(satCell).color : '셀 없음';
    wf_body_bottom.getObj("scwin").setReturnValue("[주말 색상(displayDayType 무관)] 일요일 color=" + sunColor + ", 토요일 color=" + satColor);
}



// displayDayType 설정값별 분기 — 각 모드에 필요한 검증만 출력
scwin.btn_getInfo_onclick = function (e) {
    // 공통: 적용된 displayDayType (accessibility 강제 변환 포함)
    scwin.getAppliedType();

    // 분기: 미설정은 기본값 'image' 와 동일 동작
    let dispType = target1.options.displayDayType || 'image';
    let renderType = target1.options.renderType;

    if (dispType === 'image') {
        scwin.getImageModeInfo();
    } else if (dispType === 'text') {
        scwin.getTextModeInfo();
    } else if (dispType === 'textNative') {
        scwin.getTextNativeModeInfo();
    }

    // 토/일 색상은 텍스트가 실제 표시되는 모드에서만 의미 있음
    // (image+component 는 빈 div + 배경 이미지 스프라이트라 textContent 가 없어 color 검증 불가)
    let isTextMode = (dispType === 'text' || dispType === 'textNative' || (dispType === 'image' && renderType === 'native'));
    if (isTextMode) {
        scwin.getWeekendColor();
    }
}



scwin.target1_onclick = function (e) {
    setTimeout(() => {
        scwin.getAppliedType();
    }, 100);
}
